#!/bin/sh
# Sandbox entry point for the DSH Android app.
#
# Runs inside the PRoot guest. Starts the two long-lived services the app's Web
# UI needs and then becomes the harness, so the app has exactly one process to
# supervise (and --kill-on-exit takes the rest down with it):
#
#   android-pty    node-pty shell endpoint on 127.0.0.1:$DSH_PTY_PORT, so the
#                  Web UI can offer a terminal without an active session
#   dsh web        the harness itself on 127.0.0.1:$DSH_PORT
#
# Both tokens are generated by the app and passed in the environment, because
# the Web UI (the only client) has to be told them through the native bridge.
set -eu

DSH_PORT="${DSH_PORT:-3080}"
DSH_PTY_PORT="${DSH_PTY_PORT:-3099}"
DSH_HOME="${HOME:-/root}"
DSH_INSTALL="${DSH_INSTALL:-/opt/dsh}"

# Node lives in different places per distribution (distro package: /usr/bin,
# official tarball or nvm: /usr/local/bin). Resolve it once so the same payload
# script works on any rootfs the user boots.
NODE="$(command -v node || true)"
[ -x "$NODE" ] || NODE=""
for candidate in /usr/local/bin/node /usr/bin/node; do
  [ -n "$NODE" ] && break
  [ -x "$candidate" ] && NODE="$candidate"
done
if [ -z "$NODE" ]; then
  echo "start-dsh: no node found in PATH ($PATH)"
  exit 4
fi
echo "start-dsh: node=$NODE"

# Repair an already-installed sandbox on the way up. The rootfs cannot be written
# by a hot package, so a fix to a file inside it has to be applied from here at
# boot; the script is idempotent and prints only when it changes something.
# See payload/opt/dsh/android/repair-dsh.mjs for what it fixes.
"$NODE" "$DSH_INSTALL/android/repair-dsh.mjs" "$DSH_INSTALL/node_modules" 2>&1 | sed 's/^/start-dsh: /' || true


# Recovery mode turns root's password into a one-shot token. It restores it on
# the way out (EXIT trap) and the app tries again after the process ends, but the
# app stops the sandbox by *killing* PRoot: no signal, no trap, and a restart 800
# ms later can win the race. Doing it here — at the top of every *normal* boot —
# is what makes the residue impossible to outlive one boot. Recovery mode never
# runs this script, so this can never lock a live session's password.
printf 'root:*\n' | chpasswd -e 2>/dev/null || true

mkdir -p "$DSH_HOME/.dsh"

# First run in a fresh home: seed the preinstalled profile (the app's plugin
# rows) from the immutable payload copy, so user edits afterwards persist.
# $HOME is a bind mount from app storage, so it hides the rootfs's own /root.
#
# The gate is the file the profile needs, not the directory: the app writes the
# baked hot overlay *before* this script runs (MainActivity: Payload.applyHot()
# then DshService.ensure()), and that overlay creates
# `profiles/web/node_modules/dsh-plugin-android/` — so the directory already
# exists on a brand-new install and a `[ ! -d ... ]` gate skipped the seeding
# entirely. The plugin then never entered the profile's bundles or patch layer,
# and a fresh install had neither the 「安卓沙箱」 settings page nor the terminal
# button — with both of the ways to fix that living inside the plugin that never
# loaded (reported as issue #3).
#
# A file gate also repairs the devices that shipped broken: `package.json` is
# still missing there, so the next start seeds them.
if [ ! -f "$DSH_HOME/.dsh/profiles/web/package.json" ] && [ -d "$DSH_INSTALL/dsh-home-seed" ]; then
  echo "start-dsh: seeding $DSH_HOME/.dsh from payload"
  cp -a "$DSH_INSTALL/dsh-home-seed/." "$DSH_HOME/.dsh/"
fi

# Top up a profile that already exists. The copy above is wholesale (and only
# once, because the bundle list in package.json is the user's), so a build that
# adds a bundle row or a plugin patch row would otherwise never reach an
# installed device. This one is per file and append-only: missing files are
# copied, missing rows are added, existing content is never rewritten, and any
# failure is logged and ignored rather than blocking the boot.
if [ -d "$DSH_INSTALL/dsh-home-seed" ]; then
  "$NODE" "$DSH_INSTALL/android/repair-profile.mjs" \
    "$DSH_INSTALL/dsh-home-seed" "$DSH_HOME" 2>&1 | sed 's/^/start-dsh: /' || true
fi

# The plugin is app code, not user data: refresh it on every start so an app
# update actually ships (the home itself is only seeded once, to keep sessions,
# credentials and user edits). A user who disabled the row keeps it disabled —
# that lives in cordis.patch.yml, which we never rewrite.
# Older builds ran with PRoot's --link2symlink, which left .l2s.* stand-ins for
# hard links in the harness home. They are pure artifacts, and a dangling one
# reads as a corrupt file, so clear them at startup.
rm -f "$DSH_HOME"/.l2s.* 2>/dev/null || true
find "$DSH_HOME" -maxdepth 3 -name '.l2s.*' -delete 2>/dev/null || true

# Refresh the plugin the profile resolves. The app writes this same path
# directly from the hot overlay; this copy covers the case where the guest
# boots without the app having run (fresh profile, manual start).
if [ -d "$DSH_INSTALL/dsh-plugin-android" ] && [ -d "$DSH_HOME/.dsh/profiles/web" ]; then
  target="$DSH_HOME/.dsh/profiles/web/node_modules/dsh-plugin-android"
  if [ ! -d "$target" ]; then
    mkdir -p "$(dirname "$target")"
    cp -a "$DSH_INSTALL/dsh-plugin-android" "$target"
  fi
fi

if [ -n "${DSH_PTY_TOKEN:-}" ]; then
  echo "start-dsh: pty endpoint on 127.0.0.1:$DSH_PTY_PORT"
  DSH_PTY_PORT="$DSH_PTY_PORT" \
  DSH_PTY_TOKEN="$DSH_PTY_TOKEN" \
  DSH_PTY_SHELL="${DSH_PTY_SHELL:-/bin/bash}" \
  "$NODE" "$DSH_INSTALL/android/pty-server.mjs" >>"$DSH_HOME/.dsh-pty.log" 2>&1 &
else
  echo "start-dsh: DSH_PTY_TOKEN unset, terminal disabled"
fi

if ! cd "$DSH_INSTALL" 2>/dev/null; then
  echo "start-dsh: cannot enter $DSH_INSTALL"
  echo "start-dsh: ls -la /opt:"
  ls -la /opt 2>&1 | head -20
  echo "start-dsh: ls -la $DSH_INSTALL:"
  ls -la "$DSH_INSTALL" 2>&1 | head -20
  exit 3
fi

# ------------------------------------------------------------ boot health gate
#
# dsh 0.2.1 no longer exits when a plugin fails to load. It prints
#
#     dsh: skipping profile bundle "…": <reason>
#
# and keeps serving a UI that is missing that plugin (a blank/black page is one
# of the shapes that takes). The app only counts a failure when this process
# exits *before* it announces the harness URL — a readiness resets the failure
# counter — so a half-broken harness used to run forever and automatic recovery
# mode was never entered.
#
# Hence the gate: the harness's ready line is withheld here, the shell page and
# every client plugin bundle it lists are probed, and the boot log is checked
# for skipped plugins. Only a healthy boot gets its URL announced to the app. A
# broken one exits non-zero *without* ever announcing readiness, so three
# consecutive failures make the app enter recovery mode by itself.
#
# Escape hatch: BOOT_HEALTH=off starts the harness exactly as before.
BOOT_HEALTH="${BOOT_HEALTH:-on}"
BOOT_HEALTH_TIMEOUT_MS="${BOOT_HEALTH_TIMEOUT_MS:-30000}"
export BOOT_HEALTH_TIMEOUT_MS
HARNESS_BIN="$DSH_INSTALL/node_modules/@deepseek-ai/dsh/lib/bin.js"
boot_harness() {
  "$NODE" --expose-internals "$HARNESS_BIN" web \
    --no-open --host 127.0.0.1 --port "$DSH_PORT" \
    --trusted-host "127.0.0.1:$DSH_PORT"
}

DSH_BOOT_LOG="$DSH_HOME/.dsh-boot.log"
if ! : > "$DSH_BOOT_LOG" 2>/dev/null; then
  DSH_BOOT_LOG="/tmp/.dsh-boot.log"
  : > "$DSH_BOOT_LOG" 2>/dev/null || true
fi
DSH_BOOT_PIPE="$DSH_HOME/.dsh-boot.pipe"

if [ "$BOOT_HEALTH" = "off" ]; then
  echo "start-dsh: boot health gate disabled (BOOT_HEALTH=off)"
  exec "$NODE" --expose-internals "$HARNESS_BIN" web \
    --no-open --host 127.0.0.1 --port "$DSH_PORT" \
    --trusted-host "127.0.0.1:$DSH_PORT"
fi

rm -f "$DSH_BOOT_PIPE"
if ! mkfifo "$DSH_BOOT_PIPE" 2>/dev/null; then
  echo "start-dsh: cannot create $DSH_BOOT_PIPE — starting without the boot health gate"
  exec "$NODE" --expose-internals "$HARNESS_BIN" web \
    --no-open --host 127.0.0.1 --port "$DSH_PORT" \
    --trusted-host "127.0.0.1:$DSH_PORT"
fi

# Started inline, not through boot_harness(): a function call in the background
# runs in a subshell, and $! would then be that subshell's pid — killing it would
# leave the harness orphaned and still holding the port.
"$NODE" --expose-internals "$HARNESS_BIN" web \
  --no-open --host 127.0.0.1 --port "$DSH_PORT" \
  --trusted-host "127.0.0.1:$DSH_PORT" > "$DSH_BOOT_PIPE" 2>&1 &
HARNESS_PID=$!
announced=""
while IFS= read -r line; do
  printf '%s\n' "$line" >> "$DSH_BOOT_LOG" 2>/dev/null || true
  if [ -z "$announced" ]; then
    case "$line" in
      *"http://127.0.0.1:"*"token="*)
        url=$(printf '%s\n' "$line" | grep -oE 'http://127\.0\.0\.1:[0-9]+/\?token=[A-Za-z0-9_-]+' | head -n 1 || true)
        if [ -n "$url" ]; then
          if "$NODE" "$DSH_INSTALL/android/boot-health.mjs" "$url" "$DSH_BOOT_LOG"; then
            announced=1
            printf '%s\n' "$line"
            continue
          fi
          echo "start-dsh: boot health gate: harness is up but BROKEN — readiness withheld"
          echo "start-dsh: 连续 3 次启动失败后应用会自动进入恢复模式；启动日志：$DSH_BOOT_LOG"
          kill "$HARNESS_PID" 2>/dev/null || true
          for _ in 1 2 3 4 5; do
            kill -0 "$HARNESS_PID" 2>/dev/null || break
            sleep 1
          done
          kill -9 "$HARNESS_PID" 2>/dev/null || true
          wait "$HARNESS_PID" 2>/dev/null || true
          rm -f "$DSH_BOOT_PIPE"
          exit 9
        fi
        ;;
    esac
  fi
  printf '%s\n' "$line"
done < "$DSH_BOOT_PIPE"
code=0
wait "$HARNESS_PID" || code=$?
rm -f "$DSH_BOOT_PIPE"
exit "$code"
